import{_ as o,o as a,c as t,ah as i}from"./chunks/framework.CRsDMGp2.js";const u=JSON.parse('{"title":"Guide — Direction","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/direction.md","filePath":"src/en/guide/direction.md"}'),n={name:"en/guide/direction.md"};function r(c,e,s,l,d,p){return a(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="guide-—-direction" tabindex="-1">Guide — Direction <a class="header-anchor" href="#guide-—-direction" aria-label="Permalink to &quot;Guide — Direction&quot;">​</a></h1><p>A consolidated view of the activity, across every portfolio.</p><h2 id="welcome-to-naia" tabindex="-1">Welcome to Naia <a class="header-anchor" href="#welcome-to-naia" aria-label="Permalink to &quot;Welcome to Naia&quot;">​</a></h2><p>Your Naia space gives you a consolidated view of every one of edPage group&#39;s projects and financial indicators. It&#39;s read-only, with one exception: deciding to block a project for non-payment.</p><h2 id="consolidated-project-view" tabindex="-1">Consolidated project view <a class="header-anchor" href="#consolidated-project-view" aria-label="Permalink to &quot;Consolidated project view&quot;">​</a></h2><ul><li>Access a view of every ongoing project, across all project managers and portfolios.</li><li>Spot <strong>at-risk projects</strong> at a glance, without opening each project&#39;s page: those where the Billing pole reported an overdue payment awaiting your decision (listed first), and those already blocked for non-payment, with the date they were blocked.</li></ul><h2 id="financial-indicators" tabindex="-1">Financial indicators <a class="header-anchor" href="#financial-indicators" aria-label="Permalink to &quot;Financial indicators&quot;">​</a></h2><ul><li>View the global financial indicators: invoiced and collected revenue, pending or overdue invoices, commissions due and paid to referrers.</li><li>Track each referrer&#39;s performance (number of clients referred, revenue generated, commissions due and paid).</li></ul><h2 id="deciding-on-blocking-for-non-payment" tabindex="-1">Deciding on blocking for non-payment <a class="header-anchor" href="#deciding-on-blocking-for-non-payment" aria-label="Permalink to &quot;Deciding on blocking for non-payment&quot;">​</a></h2><p>When the Billing pole reports a payment as <strong>overdue</strong> on a billable milestone, you&#39;re alerted in the app and by e-mail. Nothing is blocked automatically: it&#39;s up to you — or the administrator — to decide, from the project page.</p><ul><li><strong>Block the project</strong>: tasks already started can finish, but nobody can start a new task or validate a milestone. The client can still view, exchange and, above all, pay. The project manager and the team are notified.</li><li><strong>Do not block</strong>: the project carries on normally; the report is considered handled.</li><li>When the Billing pole reports the payment <strong>up to date</strong>, <strong>unblock the project</strong> from its page.</li></ul><p>Only the project concerned is blocked, never the same client&#39;s other projects. An internal invoice going overdue doesn&#39;t alert you: only the Billing pole&#39;s report counts.</p><h2 id="the-scope-of-your-access" tabindex="-1">The scope of your access <a class="header-anchor" href="#the-scope-of-your-access" aria-label="Permalink to &quot;The scope of your access&quot;">​</a></h2><p>Apart from blocking for non-payment, your access is limited to viewing: you have access to neither account and role management, nor security settings, nor project messaging — those remain reserved for the Administrator and the Project manager.</p>',14)])])}const g=o(n,[["render",r]]);export{u as __pageData,g as default};
